improvedPrompt:
Improved prompt:

{
  "system_instruction": "Assume the role of a seasoned brand identity professional specializing in high-end corporate design. Your task is to create a single, timeless, and scalable logo for a new company based on the detailed specifications provided below. Ensure your design is a sophisticated representation of the brand's identity that will stand the test of time and project professionalism across all applications."

  "client_background": {
    "industry": "${INDUSTRY}",
    "target_audience": "Decision-makers, investors, and industry peers",
    "brand_history": "This is a new brand, so the logo should establish a strong foundation for future growth."
  },

  "brand_essence": {
    "name": "${COMPANY_NAME}",
    "mission": "To be the leading innovator in ${INDUSTRY} by delivering ${UNIQUE_VISION}",
    "personality": "Authoritative yet approachable, established yet forward-thinking, refined yet innovative."
  },

  "design_guidelines": {
    "core_identity": "A modern, elegant, and highly legible logo that embodies ${AESTHETIC_STYLE}",
    "iconography": {
      "symbol": "Design a geometric mark that subtly yet powerfully represents ${VISUAL_SYMBOL_DESCRIPTION}",
      "symbol_size": "The symbol should have a visual weight approximately 30-40% of the full logomark."
    },
    "typography": {
      "style": "Select a bold, modern, premium sans-serif font that exudes authority and clarity",
      "scaling": "The wordmark should be scaled to be approximately 1.5-2 times larger than the symbol for optimal balance",
      "kerning": "Optimize the spacing between letters for maximum readability at small sizes"
    },
    "color_schema": {
      "primary": "${BRAND_COLOR_HEX_OR_NAME}",
      "secondary": "A complementary color that maintains the ${AESTHETIC_STYLE} feel",
      "usage": "The primary color should be dominant (70-80%), with secondary color used sparingly for accents."
    },
    "layout": {
      "composition": "A harmonious lockup of symbol and typography, with a central vertical axis and balanced negative space",
      "alignment": "The logo should be centered and equally spaced vertically and horizontally."
    },
    "negative_space": {
      "usage": "Utilize intentional white space around the logo components to create a sense of luxury and exclusivity",
      "margin": "The logo should be surrounded by a minimum of 0.5em of white space for optimal contrast."
    },
    "symbolism": {
      "metaphor": "The symbol should represent ${VISUAL_SYMBOL_DESCRIPTION} in a subtle, abstract way that evokes the desired brand emotion.",
      "interpretation": "The symbol should be open to multiple interpretations, creating intrigue and conversation."
    }
  },

  "design_standards": {
    "style_inspiration": "Draw inspiration from the Swiss Graphic Design movement, with a focus on modern corporate minimalism",
    "technical_requirements": {
      "format": "Vector format only, fully scalable without loss of clarity",
      "style": "Flat design, no 3D effects or drop shadows, clean lines and shapes",
      "color": "Solid flat colors, no gradients or textures",
      "legibility": "The logo must remain highly legible at sizes as small as 10pt."
    },
    "aesthetic_considerations": {
      "contrast": "Ensure a high level of contrast between the primary color and the background for maximum impact",
      "hierarchy": "The wordmark should have a slightly higher visual weight than the symbol."
    }
  },

  "output_specification": {
    "version": "Single logo version only",
    "mockups": "No mockups or contextual images",
    "background": "White background with a transparent layer",
    "size": "Design for both large-scale (1000px wide) and small-scale (100px wide) applications.",
    "color_options": {
      "full_color": "Primary and secondary colors",
      "one_color": "Primary color only",
      "monochrome": "Single tone of gray"
    }
  },

  "deliverables": {
    "files": "Vector files in EPS, PDF, and SVG formats",
    "guidelines": "A brief document explaining the rationale behind the design choices",
    "brand_asset_kit": "A kit including the logo in various sizes and formats, along with color codes and typography specifications."
  }
}

Please provide a single, high-resolution, professionally rendered logo that embodies the brand essence described. The logo should be designed with the aesthetic sophistication and technical precision expected from a top-tier global branding agency.
